//! Zap structured adapter: subscribes to harness IPC and renders Blocks.
//!
//! This binary connects to the harness Unix socket, streams events, and renders
//! structured Blocks to stdout. It translates typed events (Intent, Plan, Tool,
//! Approval, Agent) into visual Blocks with OSC sequences for Zap terminal.

use agentic_terminal_client::{HarnessClient, UnixSocketTransport};
use agentic_terminal_core::{Event, EventPayload, IpcRequest, IpcResponse, RuntimeStatus};
use anyhow::{Context, Result};
use std::io::{self, Write};
use std::path::PathBuf;
use uuid::Uuid;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: agentic-terminal-zap-adapter <session-id>");
        eprintln!("       agentic-terminal-zap-adapter create <prompt>");
        std::process::exit(1);
    }

    let socket_path = std::env::var_os("AGENTIC_TERMINAL_SOCKET")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(std::env::var_os("HOME").expect("HOME is set on macOS"))
                .join("Library/Application Support/Agentic Terminal")
                .join("harness.sock")
        });

    let transport = UnixSocketTransport::connect(socket_path).await?;

    match args[1].as_str() {
        "create" => {
            let prompt = args[2..].join(" ");
            create_and_attach(&transport, &prompt).await?;
        }
        session_id => {
            let session_id = Uuid::parse_str(session_id).context("Invalid session ID")?;

            // Poll for events using incremental Stream requests
            let mut last_sequence = 0u64;
            loop {
                let response = transport
                    .request(IpcRequest::Stream {
                        session_id,
                        after_sequence: last_sequence,
                    })
                    .await
                    .context("Failed to stream events")?;

                match response {
                    IpcResponse::Events { events, .. } => {
                        for event in &events {
                            render_event(event);
                            last_sequence = event.sequence;

                            if let EventPayload::Run(
                                agentic_terminal_core::RunEvent::Completed { .. }
                                | agentic_terminal_core::RunEvent::Failed { .. }
                                | agentic_terminal_core::RunEvent::Cancelled { .. },
                            ) = &event.payload
                            {
                                return Ok(());
                            }
                        }

                        if events.is_empty() {
                            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
                        }
                    }
                    IpcResponse::Error { message, .. } => {
                        anyhow::bail!("Stream error: {}", message);
                    }
                    _ => anyhow::bail!("Unexpected response: {:?}", response),
                }
            }
        }
    }

    Ok(())
}

async fn create_and_attach(transport: &UnixSocketTransport, prompt: &str) -> Result<()> {
    // Create session
    let response = transport
        .request(IpcRequest::CreateSession)
        .await
        .context("Failed to create session")?;

    let session_id = match response {
        IpcResponse::Session { session_id, status } => {
            render_block("Session", &format!("Created: {}", session_id));
            render_status(&status);
            session_id
        }
        _ => anyhow::bail!("Unexpected response: {:?}", response),
    };

    // Send prompt to start the session
    let _response = transport
        .request(IpcRequest::Prompt {
            session_id,
            text: prompt.to_string(),
        })
        .await
        .context("Failed to send prompt")?;

    // Poll for events with incremental stream requests
    let mut last_sequence = 0u64;
    loop {
        let response = transport
            .request(IpcRequest::Stream {
                session_id,
                after_sequence: last_sequence,
            })
            .await
            .context("Failed to stream events")?;

        match response {
            IpcResponse::Events { events, .. } => {
                for event in &events {
                    render_event(event);
                    last_sequence = event.sequence;

                    // Check for terminal status
                    if let EventPayload::Run(
                        agentic_terminal_core::RunEvent::Completed { .. }
                        | agentic_terminal_core::RunEvent::Failed { .. }
                        | agentic_terminal_core::RunEvent::Cancelled { .. },
                    ) = &event.payload
                    {
                        return Ok(());
                    }
                }

                // If no new events, wait a bit before polling again
                if events.is_empty() {
                    tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
                }
            }
            IpcResponse::Error { message, .. } => {
                anyhow::bail!("Stream error: {}", message);
            }
            _ => anyhow::bail!("Unexpected response: {:?}", response),
        }
    }
}

fn render_event(event: &Event) {
    match &event.payload {
        EventPayload::Session(session_event) => {
            render_block("Session", &format!("{:?}", session_event));
        }
        EventPayload::Run(run_event) => {
            render_block("Run", &format!("{:?}", run_event));
        }
        EventPayload::Intent(intent) => {
            render_block("Intent", &intent.text);
        }
        EventPayload::Plan(plan) => {
            render_block("Plan", &plan.summary);
        }
        EventPayload::Tool(tool) => {
            render_block("Tool", &format!("{:?}", tool));
        }
        EventPayload::Agent(agent) => match agent {
            agentic_terminal_core::AgentEvent::Chunk { text, .. } => {
                render_block("Agent", text);
            }
            agentic_terminal_core::AgentEvent::Final { text, .. } => {
                render_block("Agent [Final]", text);
            }
        },
        EventPayload::Approval(approval) => {
            render_block("Approval", &format!("{:?}", approval));
        }
        EventPayload::Backend(backend) => {
            render_block("Backend", &format!("{:?}", backend));
        }
        EventPayload::Notice(notice) => {
            render_block("Notice", &format!("{:?}", notice));
        }
    }
}

fn render_block(kind: &str, content: &str) {
    // Simple block rendering with visual separators
    println!("┌─ {} ─────────────────────────────────────", kind);
    for line in content.lines() {
        println!("│ {}", line);
    }
    println!("└─────────────────────────────────────────────");
    io::stdout().flush().unwrap();
}

fn render_status(status: &RuntimeStatus) {
    let status_symbol = match status {
        RuntimeStatus::Idle => "○",
        RuntimeStatus::Running => "●",
        RuntimeStatus::AwaitingApproval => "⏸",
        RuntimeStatus::Completed => "✓",
        RuntimeStatus::Failed => "✗",
        RuntimeStatus::Cancelled => "⊗",
        RuntimeStatus::InterruptedUnknown => "?",
    };

    println!("[{}] Status: {:?}", status_symbol, status);
    io::stdout().flush().unwrap();
}

use crate::ApprovalRequest;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

pub const EVENT_SCHEMA_VERSION: u16 = 1;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Event {
    pub schema_version: u16,
    pub id: Uuid,
    pub session_id: Uuid,
    pub sequence: u64,
    pub at_unix_ms: u64,
    pub payload: EventPayload,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", content = "data", rename_all = "snake_case")]
pub enum EventPayload {
    Session(SessionEvent),
    Run(RunEvent),
    Intent(IntentEvent),
    Plan(PlanEvent),
    Tool(ToolEvent),
    Agent(AgentEvent),
    Approval(ApprovalEvent),
    Backend(BackendEvent),
    Notice(NoticeEvent),
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum SessionEvent {
    Created,
    Attached,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum RunEvent {
    Started { run_id: Uuid },
    Completed { run_id: Uuid },
    Failed { run_id: Uuid, reason: String },
    Cancelled { run_id: Uuid },
    InterruptedUnknown { run_id: Uuid },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct IntentEvent {
    pub text: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PlanEvent {
    pub summary: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum ToolEvent {
    Started { name: String },
    Finished { name: String, summary: String },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum AgentEvent {
    Chunk {
        run_id: Uuid,
        chunk_id: u64,
        text: String,
    },
    Final {
        run_id: Uuid,
        text: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum ApprovalEvent {
    Requested { request: ApprovalRequest },
    Resolved { request: ApprovalRequest },
}

/// Backend and auth state changes for structured client presentation.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum BackendEvent {
    ProviderHealthy {
        profile: String,
    },
    ProviderDegraded {
        profile: String,
        reason: String,
    },
    ProviderUnavailable {
        profile: String,
        reason: String,
    },
    KeychainAvailable,
    KeychainUnavailable {
        reason: String,
    },
    TokenExpiryWarning {
        profile: String,
        expires_in_seconds: u64,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum NoticeEvent {
    PolicyAllowed,
    PolicyDenied {
        reason: String,
    },
    Runtime {
        message: String,
    },
    Legacy {
        event_kind: String,
        body: serde_json::Value,
    },
}

impl Event {
    pub fn new(session_id: Uuid, sequence: u64, payload: EventPayload) -> Self {
        let at_unix_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock before Unix epoch")
            .as_millis() as u64;
        Self {
            schema_version: EVENT_SCHEMA_VERSION,
            id: Uuid::new_v4(),
            session_id,
            sequence,
            at_unix_ms,
            payload,
        }
    }

    pub fn with_metadata(
        schema_version: u16,
        id: Uuid,
        session_id: Uuid,
        sequence: u64,
        at_unix_ms: u64,
        payload: EventPayload,
    ) -> Self {
        Self {
            schema_version,
            id,
            session_id,
            sequence,
            at_unix_ms,
            payload,
        }
    }
}

pub fn legacy_payload(
    kind: &str,
    body: serde_json::Value,
) -> Result<EventPayload, serde_json::Error> {
    match kind {
        "user_intent" => Ok(EventPayload::Intent(serde_json::from_value(body)?)),
        "approval_requested" => Ok(EventPayload::Approval(ApprovalEvent::Requested {
            request: serde_json::from_value(body)?,
        })),
        "approval_resolved" => Ok(EventPayload::Approval(ApprovalEvent::Resolved {
            request: serde_json::from_value(body)?,
        })),
        "runtime_notice" => Ok(EventPayload::Notice(NoticeEvent::Runtime {
            message: body
                .get("status")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("legacy runtime notice")
                .to_owned(),
        })),
        "policy_evaluated" => match body.get("decision").and_then(serde_json::Value::as_str) {
            Some("allow") => Ok(EventPayload::Notice(NoticeEvent::PolicyAllowed)),
            Some("deny") => Ok(EventPayload::Notice(NoticeEvent::PolicyDenied {
                reason: body
                    .get("reason")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_owned(),
            })),
            _ => Ok(EventPayload::Notice(NoticeEvent::Legacy {
                event_kind: kind.to_owned(),
                body,
            })),
        },
        _ => Ok(EventPayload::Notice(NoticeEvent::Legacy {
            event_kind: kind.to_owned(),
            body,
        })),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn payload_round_trip_is_tagged_and_typed() {
        let payload = EventPayload::Agent(AgentEvent::Chunk {
            run_id: Uuid::new_v4(),
            chunk_id: 1,
            text: "hello".into(),
        });
        let encoded = serde_json::to_string(&payload).expect("serialize payload");
        assert_eq!(
            serde_json::from_str::<EventPayload>(&encoded).expect("deserialize payload"),
            payload
        );
    }

    #[test]
    fn legacy_intent_becomes_typed_payload() {
        assert_eq!(
            legacy_payload("user_intent", serde_json::json!({ "text": "explain" }))
                .expect("convert legacy"),
            EventPayload::Intent(IntentEvent {
                text: "explain".into()
            })
        );
    }
}

//! Policy-centred local runtime for Agentic Terminal.
//!
//! The crate intentionally owns no GPUI or PTY state. It emits durable events,
//! makes permission decisions, and exposes small capability seams for the app.

