//! OSC (Operating System Command) escape sequences for terminal notifications.
//!
//! OSC sequences allow programs to communicate with the terminal emulator to
//! trigger notifications, change window titles, set badges, etc.
//!
//! Format: `ESC ] Ps ; Pt BEL` or `ESC ] Ps ; Pt ESC \`
//! where:
//! - ESC is \x1b
//! - Ps is a numeric parameter
//! - Pt is the text parameter
//! - BEL is \x07 or ESC \ is \x1b\x5c
//!
//! Common sequences:
//! - OSC 0 - Set window title and icon
//! - OSC 9 - iTerm2/Windows Terminal notifications (various sub-parameters)
//! - OSC 777 - Custom notifications (used by some terminals)
//!
//! Reference:
//! - XTerm Control Sequences: https://invisible-island.net/xterm/ctlseqs/ctlseqs.html
//! - iTerm2 Proprietary Escape Codes: https://iterm2.com/documentation-escape-codes.html

use std::fmt::Write as FmtWrite;
use std::io::{self, Write};

/// OSC sequence builder for terminal notifications.
pub struct OscNotification {
    buffer: String,
}

impl OscNotification {
    /// Create a new OSC notification with OSC 777 (custom notification).
    ///
    /// OSC 777 is used by various terminals for custom notifications and is
    /// a good choice for generic notification support.
    pub fn new(title: &str, message: &str) -> Self {
        let mut buffer = String::new();
        // OSC 777 ; notify ; title ; message BEL
        write!(
            &mut buffer,
            "\x1b]777;notify;{};{}\x07",
            Self::escape_param(title),
            Self::escape_param(message)
        )
        .expect("write to string never fails");

        Self { buffer }
    }

    /// Create an iTerm2-style notification using OSC 9.
    ///
    /// iTerm2 and Windows Terminal support OSC 9 for notifications.
    /// Format: OSC 9 ; message BEL
    pub fn iterm2(message: &str) -> Self {
        let mut buffer = String::new();
        write!(
            &mut buffer,
            "\x1b]9;{}\x07",
            Self::escape_param(message)
        )
        .expect("write to string never fails");

        Self { buffer }
    }

    /// Set the window title using OSC 0.
    ///
    /// This is widely supported across terminal emulators.
    pub fn window_title(title: &str) -> Self {
        let mut buffer = String::new();
        write!(
            &mut buffer,
            "\x1b]0;{}\x07",
            Self::escape_param(title)
        )
        .expect("write to string never fails");

        Self { buffer }
    }

    /// Create a custom OSC sequence with arbitrary parameters.
    ///
    /// Use this for terminal-specific extensions or experimental sequences.
    pub fn custom(ps: u32, pt: &str) -> Self {
        let mut buffer = String::new();
        write!(
            &mut buffer,
            "\x1b]{};{}\x07",
            ps,
            Self::escape_param(pt)
        )
        .expect("write to string never fails");

        Self { buffer }
    }

    /// Escape special characters in OSC parameters.
    ///
    /// Semicolons and control characters need to be escaped or removed
    /// to avoid breaking the OSC sequence structure.
    fn escape_param(s: &str) -> String {
        s.chars()
            .filter(|&c| c >= ' ' && c != '\x7f') // Remove control chars
            .map(|c| if c == ';' { ':' } else { c }) // Replace ; with :
            .collect()
    }

    /// Write the OSC sequence to stdout.
    pub fn emit(&self) -> io::Result<()> {
        let mut stdout = io::stdout();
        stdout.write_all(self.buffer.as_bytes())?;
        stdout.flush()
    }

    /// Get the raw OSC sequence as a string (for testing or logging).
    pub fn as_str(&self) -> &str {
        &self.buffer
    }
}

