fn render_status(status: &RuntimeStatus) {
    let status_symbol = match status {
        RuntimeStatus::Idle => "○",
        RuntimeStatus::Running => "●",
        RuntimeStatus::AwaitingApproval => "⏸",
        RuntimeStatus::Completed => "✓",
        RuntimeStatus::Failed => "✗",
        RuntimeStatus::Cancelled => "⊗",
        RuntimeStatus::InterruptedUnknown => "?",
    };

    println!("[{}] Status: {:?}", status_symbol, status);
    io::stdout().flush().unwrap();

    // Emit OSC notification for state transitions
    notify_status_change(status);
}

/// Render agent output chunks in a streaming fashion without block borders.
fn render_agent_chunk(text: &str) {
    print!("{}", text);
    io::stdout().flush().unwrap();
}

// OSC notification helpers

fn notify_status_change(status: &RuntimeStatus) {
    let (title, message) = match status {
        RuntimeStatus::Idle => ("Agent Idle", "Agent is idle and ready for input"),
        RuntimeStatus::Running => ("Agent Running", "Agent is processing your request"),
        RuntimeStatus::AwaitingApproval => (
            "Approval Needed",
            "Agent is waiting for your approval to proceed",
        ),
        RuntimeStatus::Completed => ("Completed", "Agent has completed the task successfully"),
        RuntimeStatus::Failed => ("Failed", "Agent encountered an error"),
        RuntimeStatus::Cancelled => ("Cancelled", "Task was cancelled"),
        RuntimeStatus::InterruptedUnknown => (
            "Interrupted",
            "Agent was interrupted with unknown outcome",
        ),
    };

    // Emit both OSC 777 and OSC 9 for broader terminal compatibility
    let _ = OscNotification::new(title, message).emit();
    let _ = OscNotification::iterm2(&format!("{}: {}", title, message)).emit();
}

fn notify_session_event(event: &agentic_terminal_core::SessionEvent) {
    use agentic_terminal_core::SessionEvent;

    let message = match event {
        SessionEvent::Created => "New session created",
        SessionEvent::Attached => "Attached to existing session",
    };

    let _ = OscNotification::new("Session", message).emit();
}

fn notify_run_event(event: &agentic_terminal_core::RunEvent) {
    use agentic_terminal_core::RunEvent;

    let (title, message) = match event {
        RunEvent::Started { .. } => ("Run Started", "Agent has started processing"),
        RunEvent::Completed { .. } => ("Run Completed", "Agent has finished successfully"),
        RunEvent::Failed { reason, .. } => ("Run Failed", reason.as_str()),
        RunEvent::Cancelled { .. } => ("Run Cancelled", "The run was cancelled"),
        RunEvent::InterruptedUnknown { .. } => (
            "Run Interrupted",
            "The run was interrupted with unknown outcome",
        ),
    };

    let _ = OscNotification::new(title, message).emit();
}

fn notify_approval_event(event: &agentic_terminal_core::ApprovalEvent) {
    use agentic_terminal_core::ApprovalEvent;

    match event {
        ApprovalEvent::Requested { request } => {
            let message = format!(
                "Approval needed: {} ({})",
                request.action.summary, request.reason
            );
            let _ = OscNotification::new("Approval Required", &message).emit();
        }
        ApprovalEvent::Resolved { request } => {
            let status = format!("{:?}", request.state);
            let message = format!("Approval {}: {}", status, request.action.summary);
            let _ = OscNotification::new("Approval Resolved", &message).emit();
        }
    }
}

fn notify_backend_event(event: &agentic_terminal_core::BackendEvent) {
    use agentic_terminal_core::BackendEvent;

    let (title, message) = match event {
        BackendEvent::ProviderHealthy { profile } => (
            "Provider Healthy",
            format!("Provider '{}' is healthy", profile),
        ),
        BackendEvent::ProviderDegraded { profile, reason } => (
            "Provider Degraded",
            format!("Provider '{}' is degraded: {}", profile, reason),
        ),
        BackendEvent::ProviderUnavailable { profile, reason } => (
            "Provider Unavailable",
            format!("Provider '{}' is unavailable: {}", profile, reason),
        ),
        BackendEvent::KeychainAvailable => (
            "Keychain Available",
            "Keychain access is available".to_string(),
        ),
        BackendEvent::KeychainUnavailable { reason } => (
            "Keychain Unavailable",
            format!("Keychain is unavailable: {}", reason),
        ),
        BackendEvent::TokenExpiryWarning {
            profile,
            expires_in_seconds,
        } => (
            "Token Expiring Soon",
            format!(
                "Token for '{}' expires in {} seconds",
                profile, expires_in_seconds
            ),
        ),
    };

    let _ = OscNotification::new(title, &message).emit();
}

fn notify_notice_event(event: &agentic_terminal_core::NoticeEvent) {
    use agentic_terminal_core::NoticeEvent;

    match event {
        NoticeEvent::PolicyAllowed => {
            // Don't notify for allowed actions - too noisy
        }
        NoticeEvent::PolicyDenied { reason } => {
            let _ = OscNotification::new("Policy Denied", reason).emit();
        }
        NoticeEvent::Runtime { message } => {
            let _ = OscNotification::new("Runtime Notice", message).emit();
        }
        NoticeEvent::Legacy { event_kind, .. } => {
            let _ = OscNotification::new("Notice", event_kind).emit();
        }
    }
}

