fn render_event(event: &Event, status_bar: &StatusBar) {
    // Update status bar state
    status_bar.update_from_event(event);
    status_bar.send_update();

    // Render structured block if available
    if let Some(block) = render_event_block(event) {
        println!("{}", render_block_text(&block));
        io::stdout().flush().unwrap();
        return;
    }

    // Fallback to legacy rendering
    match &event.payload {
        EventPayload::Session(session_event) => {
            render_block("Session", &format!("{:?}", session_event));
            notify_session_event(session_event);
        }
        EventPayload::Run(run_event) => {
            render_block("Run", &format!("{:?}", run_event));
            notify_run_event(run_event);
        }
        EventPayload::Intent(intent) => {
            render_block("Intent", &intent.text);
        }
        EventPayload::Plan(plan) => {
            render_block("Plan", &plan.summary);
        }
        EventPayload::Tool(tool) => {
            render_block("Tool", &format!("{:?}", tool));
        }
        EventPayload::Agent(agent) => match agent {
            agentic_terminal_core::AgentEvent::Chunk { text, .. } => {
                render_agent_chunk(text);
            }
            agentic_terminal_core::AgentEvent::Final { text, .. } => {
                render_block("Agent [Final]", text);
            }
        },
        EventPayload::Approval(approval) => {
            render_block("Approval", &format!("{:?}", approval));
            notify_approval_event(approval);
        }
        EventPayload::Backend(backend) => {
            render_block("Backend", &format!("{:?}", backend));
            notify_backend_event(backend);
        }
        EventPayload::Notice(notice) => {
            render_block("Notice", &format!("{:?}", notice));
            notify_notice_event(notice);
        }
    }
}

fn render_block(kind: &str, content: &str) {
    // Simple block rendering with visual separators
    println!("┌─ {} ─────────────────────────────────────", kind);
    for line in content.lines() {
        println!("│ {}", line);
    }
    println!("└─────────────────────────────────────────────");
    io::stdout().flush().unwrap();
}

fn render_status(status: &RuntimeStatus) {
    let status_symbol = match status {
        RuntimeStatus::Idle => "○",
        RuntimeStatus::Running => "●",
        RuntimeStatus::AwaitingApproval => "⏸",
        RuntimeStatus::Completed => "✓",
        RuntimeStatus::Failed => "✗",
        RuntimeStatus::Cancelled => "⊗",
        RuntimeStatus::InterruptedUnknown => "?",
    };

    println!("[{}] Status: {:?}", status_symbol, status);
    io::stdout().flush().unwrap();

    // Emit OSC notification for state transitions
    notify_status_change(status);
}

/// Render agent output chunks in a streaming fashion without block borders.
fn render_agent_chunk(text: &str) {
    print!("{}", text);
    io::stdout().flush().unwrap();
}

// OSC notification helpers

fn notify_status_change(status: &RuntimeStatus) {
    let (title, message) = match status {
        RuntimeStatus::Idle => ("Agent Idle", "Agent is idle and ready for input"),
        RuntimeStatus::Running => ("Agent Running", "Agent is processing your request"),
        RuntimeStatus::AwaitingApproval => (
            "Approval Needed",
            "Agent is waiting for your approval to proceed",
        ),
        RuntimeStatus::Completed => ("Completed", "Agent has completed the task successfully"),
        RuntimeStatus::Failed => ("Failed", "Agent encountered an error"),
        RuntimeStatus::Cancelled => ("Cancelled", "Task was cancelled"),
        RuntimeStatus::InterruptedUnknown => {
            ("Interrupted", "Agent was interrupted with unknown outcome")
        }
    };

    // Emit both OSC 777 and OSC 9 for broader terminal compatibility
    let _ = OscNotification::new(title, message).emit();
    let _ = OscNotification::iterm2(&format!("{}: {}", title, message)).emit();
}

